    }

    override fun read(buf: ByteBuffer): ReaditLibrary {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ReaditLibrary) = 8UL

    override fun write(value: ReaditLibrary, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



