/**
 * Errors carry a user-facing explanation and, where possible, a recovery hint.
 */
sealed class ReaditException(message: String): kotlin.Exception(message) {
        
        class UnsupportedFormat(message: String) : ReaditException(message)
        
        class Encrypted(message: String) : ReaditException(message)
        
        class Corrupt(message: String) : ReaditException(message)
        
        class NoText(message: String) : ReaditException(message)
        
        class ConversionRequired(message: String) : ReaditException(message)
        
        class Storage(message: String) : ReaditException(message)
        
        class Io(message: String) : ReaditException(message)
        
        class NotFound(message: String) : ReaditException(message)
        
        class Invalid(message: String) : ReaditException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ReaditException> {
        override fun lift(error_buf: RustBuffer.ByValue): ReaditException = FfiConverterTypeReaditError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeReaditError : FfiConverterRustBuffer<ReaditException> {
    override fun read(buf: ByteBuffer): ReaditException {
        
            return when(buf.getInt()) {
            1 -> ReaditException.UnsupportedFormat(FfiConverterString.read(buf))
            2 -> ReaditException.Encrypted(FfiConverterString.read(buf))
            3 -> ReaditException.Corrupt(FfiConverterString.read(buf))
            4 -> ReaditException.NoText(FfiConverterString.read(buf))
            5 -> ReaditException.ConversionRequired(FfiConverterString.read(buf))
            6 -> ReaditException.Storage(FfiConverterString.read(buf))
            7 -> ReaditException.Io(FfiConverterString.read(buf))
            8 -> ReaditException.NotFound(FfiConverterString.read(buf))
            9 -> ReaditException.Invalid(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: ReaditException): ULong {
        return 4UL
    }

    override fun write(value: ReaditException, buf: ByteBuffer) {
        when(value) {
            is ReaditException.UnsupportedFormat -> {
                buf.putInt(1)
                Unit
            }
            is ReaditException.Encrypted -> {
                buf.putInt(2)
                Unit
            }
            is ReaditException.Corrupt -> {
                buf.putInt(3)
                Unit
            }
            is ReaditException.NoText -> {
                buf.putInt(4)
                Unit
            }
            is ReaditException.ConversionRequired -> {
                buf.putInt(5)
                Unit
            }
            is ReaditException.Storage -> {
                buf.putInt(6)
                Unit
            }
            is ReaditException.Io -> {
                buf.putInt(7)
                Unit
            }
            is ReaditException.NotFound -> {
                buf.putInt(8)
                Unit
            }
            is ReaditException.Invalid -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



